static void wc_client_resolve_preclass_decision\(const Config\* config,
    const char\* query,
    const char\* start_host,
    int has_explicit_host,
    wc_client_preclass_decision_t\* out\)
\{
    out->action = "hint-bypassed";
    out->route_change = 0;
    out->short_circuit = 0;
    out->start_host = start_host;

    if \(!config \|\| !query \|\| !\*query\)
        return;
    if \(has_explicit_host\)
        return;

    if \(start_host && \*start_host &&
        strcasecmp\(start_host, wc_server_default_batch_host\(\)\) != 0\) \{
        out->action = "hint-applied";
        out->route_change = 1;
        return;
    \}
    if \(!config->disable_address_preclass &&
        wc_client_is_step47_early_unknown_candidate\(config, query\)\) \{
        out->action = "step47-short-circuit-unknown";
        out->route_change = 1;
        out->short_circuit = 1;
        out->start_host = "unknown";
        return;
    \}
    if \(!config->disable_address_preclass &&
        wc_client_is_p1_controlled_unknown_candidate\(config, query\)\) \{
        out->action = "preclass-short-circuit-unknown";
        out->route_change = 1;
        out->short_circuit = 1;
        out->start_host = "unknown";
        return;
    \}
    if \(!config->disable_address_preclass && config->step47_trial_enable &&
        wc_client_is_step47_trial_candidate\(config, query\)\) \{
        out->action = "step47-eligible";
        out->route_change = 0;
    \}
\}

